-- DMF0035_CLOUD_20260820 / A_DB/21_CMBO_SYNC.sql
-- SCM_ADM_CMBO_SQL_M — DMF0035 FE 가 실제 소비하는 콤보 7본 (FE grep 실측).
--   Form: useTabComboQueries(['SenderCode','ItemType','ReportBucketType','BucketType2','QtyType'])
--         + SalesSiteField comboId='UserSiteByEndCustomer'
--   Version 모달: useTabComboQueries(['MyDivision'])
--   그 외 조회조건(Division/Team/EndCustomer/BizType/PlantSite/Owner/Project/Item)은
--   @master 공용 필드 컴포넌트가 자체 콤보를 쓰므로 본 화면 전용 신규 등록 없음.
-- ⚠ 공유 콤보 표시된 5본은 타 화면도 소비 — 클라우드 본문이 사내와 다르면 덮어쓰기 충돌.
--    적용 전 00_CLOUD_PRECHECK C4(콤보 본문 diff) 확인 후 판단할 것.

-- ── QtyType : 1 row  (QTY 환산 배수 — 2026-08-06 DMF0035 작업분)

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING DUAL ON (T.SQL_ID = 'QtyType')
WHEN MATCHED THEN UPDATE SET T.MDU_DIVS_CD = 'DM', T.SQL_NM = 'QTY 환산 배수 (AS-IS DMF0003_GET_QTY_TYPE_CODE = LOOKUP MKT_FCST_UNIT_QTY)', T.SQL_DTL_CTN = 'SELECT REPLACE(SUBSTR(SEGMENT2, INSTR(SEGMENT2, ''/'') + 1), '','', '''') AS CODE'||CHR(10)||'     , SEGMENT2 AS NAME'||CHR(10)||'FROM   SCM_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'WHERE  LOOKUP_TYPE = ''MKT_FCST_UNIT_QTY'''||CHR(10)||'AND    VALID_YN = ''Y'''||CHR(10)||'ORDER BY DISPLAY_SEQ', T.USE_YN = 'Y', T.CREATED_BY = 'admin', T.CREATION_DATE = TO_DATE('20260806151425','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = TO_DATE('20260806151425','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('QtyType', 'DM', 'QTY 환산 배수 (AS-IS DMF0003_GET_QTY_TYPE_CODE = LOOKUP MKT_FCST_UNIT_QTY)', 'SELECT REPLACE(SUBSTR(SEGMENT2, INSTR(SEGMENT2, ''/'') + 1), '','', '''') AS CODE'||CHR(10)||'     , SEGMENT2 AS NAME'||CHR(10)||'FROM   SCM_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'WHERE  LOOKUP_TYPE = ''MKT_FCST_UNIT_QTY'''||CHR(10)||'AND    VALID_YN = ''Y'''||CHR(10)||'ORDER BY DISPLAY_SEQ', 'Y', 'admin', TO_DATE('20260806151425','YYYYMMDDHH24MISS'), 'admin', TO_DATE('20260806151425','YYYYMMDDHH24MISS'));

