WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('ItemType', 'DM', 'Item Type', 'SELECT        L.SEGMENT1  AS CODE,        L.SEGMENT2  AS NAME FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE  1 = 1 AND    L.LOOKUP_TYPE = ''ITEM_TYPE_CODE'' AND    L.VALID_YN    = ''Y'' ORDER BY L.DISPLAY_SEQ', 'Y', 'SYSTEM', TO_DATE('20260220155053','YYYYMMDDHH24MISS'), 'SYSTEM', TO_DATE('20260220155053','YYYYMMDDHH24MISS'));

-- ── UserSiteByEndCustomer : 1 row  (Sales Site (⚠ 공유 — SalesSiteField comboId))

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING DUAL ON (T.SQL_ID = 'UserSiteByEndCustomer')
WHEN MATCHED THEN UPDATE SET T.MDU_DIVS_CD = 'DM', T.SQL_NM = 'Sales Site (AS-IS UP_FX SiteByEndCustomer/40 1:1 — @divisionId/@endCustomer/@deptId/@asYn)', T.SQL_DTL_CTN = 'SELECT CODE, NAME FROM ('||CHR(10)||'SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME, 2 AS SORT_ORDER'||CHR(10)||'FROM SCM_MST_SITE A'||CHR(10)||'WHERE A.SITE_TYPE = ''SALES'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W'''||CHR(10)||'  AND A.DIVISION_ID <> ''40'''||CHR(10)||'  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0)'||CHR(10)||'  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0)'||CHR(10)||'  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')'||CHR(10)||'UNION ALL'||CHR(10)||'SELECT DISTINCT A.SCM_SITE_ID, A.SCM_SITE_ID, 2'||CHR(10)||'FROM SCM_MST_SITE A'||CHR(10)||'LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID'||CHR(10)||'LEFT JOIN (SELECT DISTINCT U.USER_ID, U.DEPT_ID FROM SCM_MST_SSO_USER_INFO U JOIN SCM_MST_SSO_DEPT_INFO D2 ON U.DEPT_ID = D2.DEPT_ID) C'||CHR(10)||'  ON B.OWNER = C.USER_ID'||CHR(10)||'WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W'''||CHR(10)||'  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '',40,'') > 0)'||CHR(10)||'  AND (NVL(TRIM(@deptId), ''ALL'') = ''ALL'' OR INSTR('','' || @deptId || '','', '','' || C.DEPT_ID || '','') > 0)'||CHR(10)||'  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || B.PROJECT_CODE || '','') > 0)'||CHR(10)||'  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')'||CHR(10)||'UNION ALL'||CHR(10)||'SELECT L.SEGMENT1, B.SITE_DESCRIPTION, 1'||CHR(10)||'FROM SCM_ADM_LOOKUP_MASTER_DETAIL L'||CHR(10)||'JOIN SCM_MST_SITE B ON L.SEGMENT3 = B.DIVISION_ID AND L.SEGMENT1 = B.SCM_SITE_ID'||CHR(10)||'WHERE L.LOOKUP_TYPE = ''AS_SITE_PLANT'' AND L.VALID_YN = ''Y'' AND B.VALID_YN = ''Y'''||CHR(10)||'  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || L.SEGMENT3 || '','') > 0)'||CHR(10)||') ORDER BY SORT_ORDER, CODE', T.USE_YN = 'Y', T.CREATED_BY = 'admin', T.CREATION_DATE = TO_DATE('20260723213622','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = TO_DATE('20260804204506','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('UserSiteByEndCustomer', 'DM', 'Sales Site (AS-IS UP_FX SiteByEndCustomer/40 1:1 — @divisionId/@endCustomer/@deptId/@asYn)', 'SELECT CODE, NAME FROM ('||CHR(10)||'SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME, 2 AS SORT_ORDER'||CHR(10)||'FROM SCM_MST_SITE A'||CHR(10)||'WHERE A.SITE_TYPE = ''SALES'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W'''||CHR(10)||'  AND A.DIVISION_ID <> ''40'''||CHR(10)||'  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0)'||CHR(10)||'  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0)'||CHR(10)||'  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')'||CHR(10)||'UNION ALL'||CHR(10)||'SELECT DISTINCT A.SCM_SITE_ID, A.SCM_SITE_ID, 2'||CHR(10)||'FROM SCM_MST_SITE A'||CHR(10)||'LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID'||CHR(10)||'LEFT JOIN (SELECT DISTINCT U.USER_ID, U.DEPT_ID FROM SCM_MST_SSO_USER_INFO U JOIN SCM_MST_SSO_DEPT_INFO D2 ON U.DEPT_ID = D2.DEPT_ID) C'||CHR(10)||'  ON B.OWNER = C.USER_ID'||CHR(10)||'WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W'''||CHR(10)||'  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '',40,'') > 0)'||CHR(10)||'  AND (NVL(TRIM(@deptId), ''ALL'') = ''ALL'' OR INSTR('','' || @deptId || '','', '','' || C.DEPT_ID || '','') > 0)'||CHR(10)||'  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || B.PROJECT_CODE || '','') > 0)'||CHR(10)||'  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')'||CHR(10)||'UNION ALL'||CHR(10)||'SELECT L.SEGMENT1, B.SITE_DESCRIPTION, 1'||CHR(10)||'FROM SCM_ADM_LOOKUP_MASTER_DETAIL L'||CHR(10)||'JOIN SCM_MST_SITE B ON L.SEGMENT3 = B.DIVISION_ID AND L.SEGMENT1 = B.SCM_SITE_ID'||CHR(10)||'WHERE L.LOOKUP_TYPE = ''AS_SITE_PLANT'' AND L.VALID_YN = ''Y'' AND B.VALID_YN = ''Y'''||CHR(10)||'  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || L.SEGMENT3 || '','') > 0)'||CHR(10)||') ORDER BY SORT_ORDER, CODE', 'Y', 'admin', TO_DATE('20260723213622','YYYYMMDDHH24MISS'), 'admin', TO_DATE('20260804204506','YYYYMMDDHH24MISS'));

-- ── MyDivision : 1 row  (Version 모달 Division (⚠ 공유))

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING DUAL ON (T.SQL_ID = 'MyDivision')
WHEN MATCHED THEN UPDATE SET T.MDU_DIVS_CD = 'DM', T.SQL_NM = 'MyDivision', T.SQL_DTL_CTN = '  SELECT  T1.DIVISION_ID AS CODE, T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME) AS NAME 	FROM  SCM_MST_DIVISION T1 	JOIN  SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T2 	  ON  T1.DIVISION_ID = T2.UNIT_ID 	 AND  T2.UNIT_TP_CD = ''D''    WHERE  1=1 	 AND  T1.ATTRIBUTE3 <> ''EE'' 	 AND  T1.VALID_YN = ''Y'' 	 AND  T2.USE_YN = ''Y'' 	 AND  T2.USER_ID = @sesUserId GROUP BY  T1.DIVISION_ID, T1.ATTRIBUTE1 ORDER BY  T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME)', T.USE_YN = 'Y', T.CREATED_BY = 'SYSTEM', T.CREATION_DATE = TO_DATE('20260213120525','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'SYSTEM', T.LAST_UPDATE_DATE = TO_DATE('20260213120525','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('MyDivision', 'DM', 'MyDivision', '  SELECT  T1.DIVISION_ID AS CODE, T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME) AS NAME 	FROM  SCM_MST_DIVISION T1 	JOIN  SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T2 	  ON  T1.DIVISION_ID = T2.UNIT_ID 	 AND  T2.UNIT_TP_CD = ''D''    WHERE  1=1 	 AND  T1.ATTRIBUTE3 <> ''EE'' 	 AND  T1.VALID_YN = ''Y'' 	 AND  T2.USE_YN = ''Y'' 	 AND  T2.USER_ID = @sesUserId GROUP BY  T1.DIVISION_ID, T1.ATTRIBUTE1 ORDER BY  T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME)', 'Y', 'SYSTEM', TO_DATE('20260213120525','YYYYMMDDHH24MISS'), 'SYSTEM', TO_DATE('20260213120525','YYYYMMDDHH24MISS'));

COMMIT;